export const MUSKELN = [{"ausatmen":"In Ruhe entspannt es sich, die Kuppel steigt passiv zurück. Beim Singen kann es am Anfang einer Phrase bremsend aktiv bleiben (Druck feinsteuern).","id":"zwerchfell","lage":"Kuppelförmige Muskelplatte unter der Lunge, quer durch den Rumpf; Rand an den unteren Rippen, Lendenwirbeln und Brustbeinende; Mitte = Sehnenplatte (Herz liegt darauf).","name_ui":"Zwerchfell","rolle":"Haupt-Einatemmuskel. Zieht sich zusammen → Kuppel wird flacher und rückt nach unten → Brustraum wird höher, Luft strömt ein. Schiebt dabei Bauchinhalt nach unten/vorn (Bauchwand wölbt sich) und weitet über die Anlagezone die unteren Rippen."},{"id":"zwischenrippen_aussen","lage":"Schräge Fasern zwischen den Rippen, außen am Brustkorb.","name_ui":"Äußere Zwischenrippenmuskeln","rolle":"Einatmen: heben die Rippen. Untere Rippen schwingen seitlich hoch wie ein Eimerhenkel → Brustkorb wird breiter. Obere Rippen heben das Brustbein nach vorn-oben wie ein Pumpenschwengel → Brustkorb wird tiefer."},{"id":"zwischenrippen_innen","lage":"Unter den äußeren, Fasern quer dazu.","name_ui":"Innere Zwischenrippenmuskeln","rolle":"Aktives Ausatmen: senken und verengen die Rippen. In Ruhe kaum nötig."},{"id":"bauchmuskeln","lage":"Bauchwand vorn und seitlich; quere Schicht wie ein Gürtel um die Taille.","name_ui":"Bauchmuskeln (gerade, schräge, quere)","rolle":"Aktives Ausatmen: drücken den Bauchinhalt nach innen/oben, so wird das entspannte Zwerchfell hochgeschoben; ziehen die unteren Rippen nach unten. In Ruhe beim Ausatmen kaum aktiv. Beim Singen, Husten, langen Tönen und Staccato aktiv; bei Opernsängern stärker als bei Gesangsstudierenden gemessen."},{"id":"treppenmuskeln","lage":"Seitlich am Hals von der Halswirbelsäule zur 1./2. Rippe.","name_ui":"Treppenmuskeln (seitlicher Hals)","rolle":"Heben die oberste Rippe; leicht auch in Ruhe beteiligt, stark beim tiefen/angestrengten Einatmen. Bei sinkendem Atembedarf geht ihre Aktivität zurück (EMG bei Sängern)."},{"id":"kopfwender","lage":"Schräg am Hals vom Ohr zum Brustbein/Schlüsselbein.","name_ui":"Kopfwender","rolle":"Atemhilfsmuskel: hebt Brustbein und Schlüsselbein bei angestrengtem Einatmen (Hochatmung). Beim Singen in sehr hoher Lage und am Ende langer, lauter Phrasen deutlich aktiver gemessen."},{"id":"trapez_oben","lage":"Nacken bis Schulterhöhe.","name_ui":"Oberer Kapuzenmuskel","rolle":"Hebt die Schultern. Bei Hochatmung sichtbar aktiv; Spannung hier geht nach Gesangslehre oft mit Hals-/Kehlkopfspannung einher (plausibel, nicht kontrolliert geprüft). Mit Biofeedback ließ sich die Aktivität bei Sängern senken."},{"id":"brustmuskel_klein","lage":"Vordere obere Brust, unter dem großen Brustmuskel.","name_ui":"Kleiner Brustmuskel (und großer, bei aufgestützten Armen)","rolle":"Atemhilfsmuskel beim angestrengten Einatmen; der große Brustmuskel hilft vor allem, wenn die Arme aufgestützt sind (Kutschersitz)."},{"id":"ruecken_breit","lage":"Seitlich-hinten vom unteren Rücken zur Achsel.","name_ui":"Breiter Rückenmuskel","rolle":"Hilft beim kräftigen Ausatmen (Husten). Bei Sängerinnen am Ende einer Atemphrase und bei Koloraturen in Stößen aktiv gemessen."}];
